/**
 * Posts files inline to WaSOS via the v1 multipart/form-data endpoint.
 * Mirrors Handle Rayvn files upload — uses nodeFetch directly.
 *
 * WaSOS has no separate file upload API — files must be sent together
 * with the message in a single POST. nodeFetch is used directly (same
 * pattern as Handle Rayvn files upload) to avoid Node-RED HTTP node
 * behaviour with Buffer payloads.
 *
 * When files are loaded:
 *   - Builds multipart body
 *   - POSTs to /api/v1/chat/messages/{room}
 *   - Sets msg.statusCode and msg._wasos_posted = true
 *   - POST to Wasos chat bypasses its HTTP node for this case
 *
 * When no buffers are available:
 *   - Falls through without _wasos_posted so the normal JSON path is used
 *
 * Upload failures are appended to metadata.files.failed.
 * Content is patched before the POST (mirrors Patch receiver text logic).
 */
const utils  = global.get("utils");
const target = msg.metadata.target;
const base   = global.get("parat_bridge").base_urls.wasos;
const buffer = global.get("files." + file.context_key);
node.warn("buffer: " + (buffer ? buffer.length : "null") + " bytes, key: " + file.context_key);
const items  = msg.metadata.files.items;

const loaded = [];
const failed = [];

node.warn("file type/name: " + JSON.stringify(items.map(f => ({ name: f.name, type: f.type }))));

for (const file of items) {
    const buffer = global.get("files." + file.context_key);
    if (!buffer || buffer.length === 0) {
        node.warn("No buffer for: " + file.context_key);
        failed.push({ name: file.name || "unknown file", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        continue;
    }
    loaded.push({ file, buffer });
    node.log("Queuing for WaSOS: " + file.name + " (" + buffer.length + " bytes)");
}

if (failed.length > 0) {
    msg.metadata.files.failed = [...msg.metadata.files.failed, ...failed];
}

// Patch content before POST — must happen here as payload becomes a Buffer
const all_failed = msg.metadata.files.failed;
if (all_failed.length > 0) {
    const total  = loaded.length + all_failed.length;
    const notice = " [" + all_failed.length + "/" + total
        + " vedlegg ikke overført. Avsender mottar instruks om alternativ håndtering]";
    msg.payload.content = (msg.payload.content || "") + notice;
}

if (loaded.length === 0) {
    return msg;
}

// Build multipart/form-data body
const boundary = "----PBWasosBoundary" + Date.now();
const chunks   = [];

for (const field of ["content", "callsign"]) {
    if (msg.payload[field] != null) {
        chunks.push(Buffer.from(
            `--${boundary}\r\nContent-Disposition: form-data; name="${field}"\r\n\r\n${msg.payload[field]}\r\n`
        ));
    }
}

if (msg.payload.isLocation != null) {
    chunks.push(Buffer.from(
        `--${boundary}\r\nContent-Disposition: form-data; name="isLocation"\r\n\r\n${msg.payload.isLocation}\r\n`
    ));
}

for (const { file, buffer } of loaded) {
    chunks.push(Buffer.from(
        `--${boundary}\r\nContent-Disposition: form-data; name="files"; filename="${file.name || "file.bin"}"\r\nContent-Type: ${file.type || "application/octet-stream"}\r\n\r\n`
    ));
    chunks.push(buffer);
    chunks.push(Buffer.from("\r\n"));
}

chunks.push(Buffer.from(`--${boundary}--\r\n`));
const body = Buffer.concat(chunks);

try {
    const res = await nodeFetch(
        base + "/api/v1/chat/messages/" + target.client_specific.chatroom_name,
        {
            method:  "POST",
            headers: {
                "x-api-key":    target.api_key,
                "Content-Type": "multipart/form-data; boundary=" + boundary
            },
            body
        }
    );

    msg.statusCode    = res.status;
    msg._wasos_posted = true;

    if (!res.ok) {
        node.warn("WaSOS multipart POST returned " + res.status + ": " + (await res.text()));
    }
} catch (e) {
    node.warn("WaSOS multipart POST error: " + e.message);
    msg.statusCode    = 500;
    msg._wasos_posted = true;
}

return msg;
